colossal_kraken_breach.source:
export const envelope = [64, 48, 64];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Uint16Array(W * H * D);
  const palette = ["minecraft:air"];
  const pMap = new Map();
  pMap.set("minecraft:air", 0);

  function getBlockId(name) {
    let id = pMap.get(name);
    if (id === undefined) {
      id = palette.length;
      palette.push(name);
      pMap.set(name, id);
    }
    return id;
  }

  function setVoxel(x, y, z, blockName) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    const idx = (y * D + z) * W + x;
    grid[idx] = getBlockId(blockName);
  }

  function getVoxel(x, y, z) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return 0;
    return grid[(y * D + z) * W + x];
  }

  // Theme roles with safe fallbacks
  const themePavement = api.theme?.ground?.pavement || "minecraft:smooth_quartz";
  const themeKerb = api.theme?.ground?.kerb || "minecraft:polished_andesite";
  const themeCoping = api.theme?.ground?.coping || "minecraft:smooth_stone_slab";
  const themePlinth = api.theme?.ground?.plinth || "minecraft:stone_bricks";
  const themeWallCore = api.theme?.wall?.core || "minecraft:stone_bricks";
  const themeWallParapet = api.theme?.wall?.parapet || "minecraft:stone_brick_wall";
  const themeStone = api.theme?.stone?.primary || "minecraft:stone_bricks";

  // --- 1. WATERFRONT PROMENADE & SEABED FOUNDATION ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const h = api.heightAt(x, z);
      const minY = Math.max(0, Math.min(0, h));

      if (z <= 14) {
        // Promenade Zone
        for (let y = minY; y <= 5; y++) {
          setVoxel(x, y, z, themePlinth);
        }

        const breachDist = Math.hypot((x - 32) * 0.8, (z - 13) * 1.1);

        if (breachDist < 11.0) {
          // Breached & shattered plaza
          if (breachDist > 7.5) {
            const buckled = ((x * 7 + z * 13) % 5 === 0) ? 7 : 6;
            setVoxel(x, buckled, z, themeStone);
            if ((x + z) % 7 === 0) {
              setVoxel(x, buckled + 1, z, "minecraft:iron_bars");
            }
          } else {
            // Flooded crater cavity
            const craterDepth = Math.max(minY + 1, Math.floor(6 - (7.5 - breachDist) * 0.6));
            for (let y = craterDepth; y <= 6; y++) {
              if (y === 6 && (x + z) % 2 === 0) {
                setVoxel(x, y, z, "minecraft:white_stained_glass");
              } else {
                setVoxel(x, y, z, "minecraft:water");
              }
            }
          }
        } else {
          // Intact Hellenist Promenade Pavement
          const isBorder = (x % 6 === 0 || z % 6 === 0);
          const check = ((Math.floor(x / 2) + Math.floor(z / 2)) % 2 === 0);
          const tile = isBorder ? themeKerb : (check ? themePavement : "minecraft:polished_diorite");
          setVoxel(x, 6, z, tile);
        }
      } else {
        // Coastal Seabed & Water Zone
        const seabedY = Math.max(minY, Math.floor(3 - (z - 14) * 0.07));
        for (let y = minY; y <= seabedY; y++) {
          setVoxel(x, y, z, "minecraft:gravel");
        }
        for (let y = seabedY + 1; y <= 4; y++) {
          setVoxel(x, y, z, "minecraft:water");
        }
      }
    }
  }

  // --- 2. SEAWALL & BREACH MONOLITHS ---
  for (let x = 0; x < W; x++) {
    const isIntact = (x < 17 || x > 47);
    if (isIntact) {
      for (let y = 0; y <= 7; y++) {
        setVoxel(x, y, 14, themeWallCore);
        setVoxel(x, y, 15, themeWallCore);
      }
      setVoxel(x, 8, 14, themeCoping);
      setVoxel(x, 8, 15, themeWallParapet);
      if (x % 6 === 3) {
        setVoxel(x, 8, 14, "minecraft:polished_blackstone_wall");
        setVoxel(x, 9, 14, "minecraft:polished_blackstone_wall");
      }
    } else {
      // Smashed jagged seawall remains
      const wallH = 2 + Math.floor(Math.sin(x * 0.55) * 2.5);
      for (let y = 0; y <= wallH; y++) {
        setVoxel(x, y, 14, (y % 2 === 0) ? themeStone : "minecraft:polished_deepslate");
      }
      if ((x * 3) % 4 === 0) {
        setVoxel(x, wallH + 1, 14, "minecraft:iron_bars");
      }
    }
  }

  // --- 3. CLASSICAL HELLENIST MONUMENTAL COLONNADES ---
  function buildColumn(bx, bz, maxH, intact) {
    for (let cy = 7; cy <= maxH; cy++) {
      if (cy === 7) {
        setVoxel(bx, cy, bz, "minecraft:smooth_quartz");
      } else if (cy < maxH) {
        setVoxel(bx, cy, bz, "minecraft:quartz_pillar");
      } else if (intact) {
        setVoxel(bx, cy, bz, "minecraft:smooth_quartz");
        setVoxel(bx - 1, cy, bz, "minecraft:smooth_quartz");
        setVoxel(bx + 1, cy, bz, "minecraft:smooth_quartz");
      }
    }
  }

  // Intact West Portico
  buildColumn(6, 5, 15, true);
  buildColumn(12, 5, 15, true);
  for (let bx = 4; bx <= 14; bx++) {
    setVoxel(bx, 16, 5, "minecraft:smooth_quartz");
    setVoxel(bx, 17, 5, "minecraft:quartz_slab");
  }
  for (let px = 5; px <= 13; px++) {
    const pdist = Math.abs(px - 9);
    for (let py = 0; py <= (3 - pdist); py++) {
      setVoxel(px, 18 + py, 5, "minecraft:smooth_quartz");
    }
  }

  // Intact East Portico
  buildColumn(52, 5, 15, true);
  buildColumn(58, 5, 15, true);
  for (let bx = 50; bx <= 60; bx++) {
    setVoxel(bx, 16, 5, "minecraft:smooth_quartz");
    setVoxel(bx, 17, 5, "minecraft:quartz_slab");
  }
  for (let px = 51; px <= 59; px++) {
    const pdist = Math.abs(px - 55);
    for (let py = 0; py <= (3 - pdist); py++) {
      setVoxel(px, 18 + py, 5, "minecraft:smooth_quartz");
    }
  }

  // Smashed central columns
  buildColumn(20, 5, 9, false);
  setVoxel(20, 7, 7, "minecraft:quartz_pillar");
  setVoxel(20, 7, 8, "minecraft:quartz_pillar");
  setVoxel(21, 7, 9, "minecraft:smooth_quartz");

  buildColumn(44, 5, 10, false);
  setVoxel(43, 7, 6, "minecraft:quartz_pillar");
  setVoxel(42, 7, 6, "minecraft:quartz_pillar");
  setVoxel(41, 7, 7, "minecraft:smooth_quartz");

  // Modern Streetlight Fixtures & Checkpoint line
  for (const lx of [4, 60]) {
    setVoxel(lx, 7, 2, "minecraft:polished_deepslate");
    setVoxel(lx, 8, 2, "minecraft:iron_bars");
    setVoxel(lx, 9, 2, "minecraft:iron_bars");
    setVoxel(lx, 10, 2, "minecraft:sea_lantern");
  }
  for (let bx = 16; bx <= 22; bx++) {
    setVoxel(bx, 7, 2, (bx % 2 === 0) ? "minecraft:yellow_concrete" : "minecraft:black_concrete");
  }
  for (let bx = 42; bx <= 48; bx++) {
    setVoxel(bx, 7, 2, (bx % 2 === 0) ? "minecraft:yellow_concrete" : "minecraft:black_concrete");
  }

  // --- 4. COLOSSAL LEVIATHAN TORSO & CARAPACE ---
  for (let y = 1; y <= 39; y++) {
    const v = (y - 1) / 38.0;
    const cx = 32.0;
    const cz = 41.0 - 14.5 * Math.pow(v, 1.25);
    let rx = 10.2 * Math.sin(v * 2.4 + 0.35) * (1.0 - 0.22 * v);
    let rz = 11.8 * Math.sin(v * 2.4 + 0.35) * (1.0 - 0.18 * v);
    if (y < 6) {
      rx += (6 - y) * 1.3;
      rz += (6 - y) * 1.3;
    }

    const minX = Math.floor(cx - rx - 1);
    const maxX = Math.ceil(cx + rx + 1);
    const minZ = Math.floor(cz - rz - 1);
    const maxZ = Math.ceil(cz + rz + 1);

    for (let x = minX; x <= maxX; x++) {
      for (let z = minZ; z <= maxZ; z++) {
        const dx = (x - cx) / Math.max(1, rx);
        const dz = (z - cz) / Math.max(1, rz);
        const d2 = dx * dx + dz * dz;
        if (d2 <= 1.0) {
          const distFrac = Math.sqrt(d2);
          let blk = "minecraft:dark_prismarine";
          if (dz > 0.25) {
            // Dorsal carapace
            blk = (distFrac > 0.8 && ((x + y + z) % 3 === 0)) ? "minecraft:sculk" : "minecraft:dark_prismarine";
          } else if (dz < -0.25) {
            // Ventral throat/belly facing city
            blk = (distFrac > 0.82) ? "minecraft:prismarine_bricks" : "minecraft:prismarine";
          } else {
            blk = ((x ^ y) & 1) ? "minecraft:dark_prismarine" : "minecraft:prismarine_bricks";
          }
          setVoxel(x, y, z, blk);
        }
      }
    }
  }

  // Dorsal Carapace Spines along the spine
  for (let spineY = 12; spineY <= 36; spineY += 4) {
    const v = (spineY - 1) / 38.0;
    const cz = 41.0 - 14.5 * Math.pow(v, 1.25);
    const rz = 11.8 * Math.sin(v * 2.4 + 0.35) * (1.0 - 0.18 * v);
    const spineLen = 4 + Math.floor(Math.sin(v * Math.PI) * 3.5);
    for (let s = 0; s < spineLen; s++) {
      const sx = 32;
      const sy = spineY + Math.floor(s * 0.6);
      const sz = Math.round(cz + rz + s);
      setVoxel(sx, sy, sz, "minecraft:dark_prismarine");
      setVoxel(sx - 1, sy, sz, "minecraft:dark_prismarine");
      setVoxel(sx + 1, sy, sz, "minecraft:dark_prismarine");
      if (s === spineLen - 1) {
        setVoxel(sx, sy + 1, sz, "minecraft:sculk");
      }
    }
  }

  // Maw & Concentric Hooked Teeth
  const mawX = 32, mawY = 16, mawZ = 24;
  for (let my = mawY - 5; my <= mawY + 5; my++) {
    for (let mx = mawX - 5; mx <= mawX + 5; mx++) {
      for (let mz = mawZ - 4; mz <= mawZ + 4; mz++) {
        const dmx = mx - mawX;
        const dmy = my - mawY;
        const rMaw = Math.sqrt(dmx * dmx + dmy * dmy);
        const cavity = 4.3 - (mz - mawZ + 2) * 0.55;
        if (rMaw < cavity && mz >= mawZ - 2) {
          if (mz >= mawZ + 2) {
            setVoxel(mx, my, mz, "minecraft:ochre_froglight");
          } else if (mz >= mawZ && rMaw > cavity - 1.2) {
            setVoxel(mx, my, mz, "minecraft:bone_block");
          } else {
            setVoxel(mx, my, mz, "minecraft:air");
          }
        }
      }
    }
  }

  // Teeth ring
  for (let angle = 0; angle < Math.PI * 2; angle += Math.PI / 6) {
    const tx = Math.round(mawX + Math.cos(angle) * 3.5);
    const ty = Math.round(mawY + Math.sin(angle) * 3.5);
    setVoxel(tx, ty, mawZ - 1, "minecraft:smooth_quartz");
    const tipX = Math.round(mawX + Math.cos(angle) * 2.2);
    const tipY = Math.round(mawY + Math.sin(angle) * 2.2);
    setVoxel(tipX, tipY, mawZ, "minecraft:pointed_dripstone");
  }

  // Glowing Sea Lantern Eyes
  // Central Cyclopean Eye
  for (let ey = 23; ey <= 25; ey++) {
    for (let ex = 31; ex <= 33; ex++) {
      setVoxel(ex, ey, 22, "minecraft:sea_lantern");
    }
  }
  setVoxel(32, 24, 21, "minecraft:obsidian");
  setVoxel(32, 25, 21, "minecraft:crying_obsidian");
  setVoxel(32, 23, 21, "minecraft:crying_obsidian");

  // Secondary & Tertiary Eyes
  setVoxel(26, 23, 23, "minecraft:sea_lantern");
  setVoxel(26, 23, 22, "minecraft:dark_prismarine");
  setVoxel(38, 23, 23, "minecraft:sea_lantern");
  setVoxel(38, 23, 22, "minecraft:dark_prismarine");

  setVoxel(28, 28, 23, "minecraft:verdant_froglight");
  setVoxel(36, 28, 23, "minecraft:verdant_froglight");

  // --- 5. TENTACLE PROCEDURAL SPLINE RASTERIZER ---
  function bezier5(p0, p1, p2, p3, p4, t) {
    const u = 1 - t;
    const tt = t * t;
    const uu = u * u;
    const uuu = uu * u;
    const ttt = tt * t;
    const uuuu = uu * uu;
    const tttt = tt * tt;
    const c0 = uuuu;
    const c1 = 4 * uuu * t;
    const c2 = 6 * uu * tt;
    const c3 = 4 * u * ttt;
    const c4 = tttt;
    return [
      c0 * p0[0] + c1 * p1[0] + c2 * p2[0] + c3 * p3[0] + c4 * p4[0],
      c0 * p0[1] + c1 * p1[1] + c2 * p2[1] + c3 * p3[1] + c4 * p4[1],
      c0 * p0[2] + c1 * p1[2] + c2 * p2[2] + c3 * p3[2] + c4 * p4[2]
    ];
  }

  const tentacles = [
    // 1. Left Promenade Crusher
    {
      p0: [26, 8, 30], p1: [16, 20, 24], p2: [10, 26, 15], p3: [7, 14, 7], p4: [12, 6, 4],
      r0: 3.8, r1: 1.1, sn: [0.4, -0.8, -0.4]
    },
    // 2. Right Promenade Crusher
    {
      p0: [38, 8, 30], p1: [48, 20, 24], p2: [54, 26, 15], p3: [57, 14, 7], p4: [52, 6, 4],
      r0: 3.8, r1: 1.1, sn: [-0.4, -0.8, -0.4]
    },
    // 3. Sky Whiplash Left
    {
      p0: [29, 16, 34], p1: [20, 28, 28], p2: [18, 43, 22], p3: [24, 46, 14], p4: [28, 39, 10],
      r0: 3.2, r1: 0.9, sn: [0.4, -0.6, -0.6]
    },
    // 4. Sky Whiplash Right
    {
      p0: [35, 16, 34], p1: [44, 28, 28], p2: [46, 43, 22], p3: [40, 46, 14], p4: [36, 39, 10],
      r0: 3.2, r1: 0.9, sn: [-0.4, -0.6, -0.6]
    },
    // 5. Low Breach Grasp Left
    {
      p0: [24, 6, 26], p1: [18, 14, 19], p2: [16, 12, 12], p3: [22, 8, 8], p4: [26, 6, 6],
      r0: 2.9, r1: 1.0, sn: [0.2, -0.7, -0.6]
    },
    // 6. Low Breach Grasp Right
    {
      p0: [40, 6, 26], p1: [46, 14, 19], p2: [48, 12, 12], p3: [42, 8, 8], p4: [38, 6, 6],
      r0: 2.9, r1: 1.0, sn: [-0.2, -0.7, -0.6]
    },
    // 7. Deep Water Flank Left
    {
      p0: [24, 4, 42], p1: [14, 12, 48], p2: [8, 22, 44], p3: [8, 16, 34], p4: [14, 6, 28],
      r0: 2.8, r1: 0.9, sn: [0.6, -0.4, 0.6]
    },
    // 8. Deep Water Flank Right
    {
      p0: [40, 4, 42], p1: [50, 12, 48], p2: [56, 22, 44], p3: [56, 16, 34], p4: [50, 6, 28],
      r0: 2.8, r1: 0.9, sn: [-0.6, -0.4, 0.6]
    }
  ];

  for (const tent of tentacles) {
    const snLen = Math.hypot(tent.sn[0], tent.sn[1], tent.sn[2]) || 1;
    const sn = [tent.sn[0] / snLen, tent.sn[1] / snLen, tent.sn[2] / snLen];
    const steps = 110;

    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const pos = bezier5(tent.p0, tent.p1, tent.p2, tent.p3, tent.p4, t);
      const r = tent.r0 * (1 - t) + tent.r1 * t;

      const minX = Math.floor(pos[0] - r - 1);
      const maxX = Math.ceil(pos[0] + r + 1);
      const minY = Math.floor(pos[1] - r - 1);
      const maxY = Math.ceil(pos[1] + r + 1);
      const minZ = Math.floor(pos[2] - r - 1);
      const maxZ = Math.ceil(pos[2] + r + 1);

      for (let x = minX; x <= maxX; x++) {
        for (let y = minY; y <= maxY; y++) {
          for (let z = minZ; z <= maxZ; z++) {
            const dx = x - pos[0];
            const dy = y - pos[1];
            const dz = z - pos[2];
            const distSq = dx * dx + dy * dy + dz * dz;

            if (distSq <= r * r) {
              const dist = Math.sqrt(distSq);
              const nx = dist > 0.001 ? dx / dist : 0;
              const ny = dist > 0.001 ? dy / dist : 0;
              const nz = dist > 0.001 ? dz / dist : 0;
              const dot = nx * sn[0] + ny * sn[1] + nz * sn[2];

              let blk = "minecraft:dark_prismarine";
              if (dot > 0.42) {
                // Sucker Disc Underside
                const suckerPhase = (t * 22.0) % 1.0;
                if (dist > r - 1.1 && dot > 0.62 && suckerPhase > 0.25 && suckerPhase < 0.75) {
                  blk = (Math.sin(t * 35) > 0) ? "minecraft:sea_lantern" : "minecraft:ochre_froglight";
                } else if (dist > r - 0.9 && dot > 0.5) {
                  blk = "minecraft:prismarine_bricks";
                } else {
                  blk = "minecraft:prismarine";
                }
              } else if (dot < -0.42) {
                // Dorsal Carapace
                blk = (dist > r - 0.85 && ((x + y + z) % 3 === 0)) ? "minecraft:sculk" : "minecraft:dark_prismarine";
              } else {
                blk = ((x + y) % 2 === 0) ? "minecraft:dark_prismarine" : "minecraft:prismarine_bricks";
              }

              setVoxel(x, y, z, blk);
            }
          }
        }
      }
    }
  }

  // --- 6. FROTHING SEA SURGES & WAVE IMPACTS ---
  for (let x = 10; x <= 54; x++) {
    for (let z = 15; z <= 56; z++) {
      const distToCenter = Math.hypot(x - 32, z - 38);
      if (distToCenter >= 8.5 && distToCenter <= 21.0) {
        const waveH = 5 + Math.floor(Math.sin(distToCenter * 0.85 + ((x * 3) ^ z) * 0.1) * 2.2);
        for (let y = 4; y <= waveH; y++) {
          const cur = getVoxel(x, y, z);
          if (cur === 0 || cur === pMap.get("minecraft:water")) {
            const isTop = (y === waveH);
            const foam = isTop
              ? (((x + z) % 3 === 0) ? "minecraft:sea_lantern" : "minecraft:white_stained_glass")
              : "minecraft:cyan_stained_glass";
            setVoxel(x, y, z, foam);
          }
        }
      }
    }
  }

  // --- 7. CONNECTIVITY ENFORCEMENT BFS ---
  const visited = new Uint8Array(W * H * D);
  const queue = [];

  // Seed with all solid foundation voxels at y <= 6
  for (let y = 0; y <= 6; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const idx = (y * D + z) * W + x;
        if (grid[idx] !== 0) {
          visited[idx] = 1;
          queue.push(idx);
        }
      }
    }
  }

  let head = 0;
  const offX = [1, -1, 0, 0, 0, 0];
  const offY = [0, 0, 1, -1, 0, 0];
  const offZ = [0, 0, 0, 0, 1, -1];

  while (head < queue.length) {
    const curr = queue[head++];
    const cx = curr % W;
    const rem = (curr - cx) / W;
    const cz = rem % D;
    const cy = (rem - cz) / D;

    for (let i = 0; i < 6; i++) {
      const nx = cx + offX[i];
      const ny = cy + offY[i];
      const nz = cz + offZ[i];

      if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
        const nidx = (ny * D + nz) * W + nx;
        if (grid[nidx] !== 0 && !visited[nidx]) {
          visited[nidx] = 1;
          queue.push(nidx);
        }
      }
    }
  }

  // Clear any disconnected floating fragments
  for (let i = 0; i < W * H * D; i++) {
    if (grid[i] !== 0 && !visited[i]) {
      grid[i] = 0;
    }
  }

  // --- 8. EMIT BLOCKS TO API ---
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const id = grid[(y * D + z) * W + x];
        if (id !== 0) {
          api.set(x, y, z, palette[id]);
        }
      }
    }
  }

  return {
    name: "colossal_kraken_breach",
    seatY: 0,
    anchors: {
      front: [32, 16, 0],
      promenade: [32, 6, 0],
      breach: [32, 8, 14]
    }
  };
}

monumental_athena_colossus.source:
export const envelope = [32, 56, 32];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Map();

  function setBlock(x, y, z, block) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix < 0 || ix >= W || iy < 0 || iy >= H || iz < 0 || iz >= D) return;
    grid.set(`${ix},${iy},${iz}`, block);
  }

  function fillBox(x1, y1, z1, x2, y2, z2, block) {
    const minX = Math.max(0, Math.min(x1, x2));
    const maxX = Math.min(W - 1, Math.max(x1, x2));
    const minY = Math.max(0, Math.min(y1, y2));
    const maxY = Math.min(H - 1, Math.max(y1, y2));
    const minZ = Math.max(0, Math.min(z1, z2));
    const maxZ = Math.min(D - 1, Math.max(z1, z2));
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          grid.set(`${x},${y},${z}`, block);
        }
      }
    }
  }

  // Materials & Palette
  const stonePrim = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const stoneAcc = api.theme?.stone?.accent || "minecraft:chiseled_quartz_block";
  const stoneWall = api.theme?.stone?.wall || "minecraft:prismarine_wall";
  const groundPav = api.theme?.ground?.pavement || "minecraft:smooth_quartz";
  const groundPlinth = api.theme?.ground?.plinth || "minecraft:polished_diorite";

  const quartz = "minecraft:smooth_quartz";
  const quartzStairs = "minecraft:smooth_quartz_stairs";
  const quartzSlab = "minecraft:smooth_quartz_slab[type=bottom]";
  const quartzPillar = "minecraft:quartz_pillar[axis=y]";
  const chiseledQuartz = "minecraft:chiseled_quartz_block";
  const calcite = "minecraft:calcite";

  const wCopper = "minecraft:weathered_copper";
  const wCutCopper = "minecraft:weathered_cut_copper";
  const wCopperStairs = "minecraft:weathered_cut_copper_stairs";
  const wCopperSlab = "minecraft:weathered_cut_copper_slab[type=bottom]";
  const oxCopper = "minecraft:oxidized_copper";
  const oxCutCopper = "minecraft:oxidized_cut_copper";

  const seaLantern = "minecraft:sea_lantern";
  const gold = "minecraft:gold_block";
  const prismarineWall = "minecraft:prismarine_wall";

  // -------------------------------------------------------------
  // 1. FORTIFIED COASTAL BASTION (Y = 0 to 9)
  // -------------------------------------------------------------
  const cx = 15.5;
  const cz = 15.5;

  function isBastion(x, z) {
    const dx = Math.abs(x - cx);
    const dz = Math.abs(z - cz);
    return dx <= 14.5 && dz <= 14.5 && dx + dz <= 21.0;
  }

  function isBastionRim(x, z) {
    const dx = Math.abs(x - cx);
    const dz = Math.abs(z - cz);
    return (dx >= 13.0 || dz >= 13.0 || dx + dz >= 19.0) && isBastion(x, z);
  }

  // Bastion Mass & Walls
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isBastion(x, z)) {
        // Foundation & Ground footing
        setBlock(x, 0, z, groundPlinth);

        for (let y = 1; y <= 8; y++) {
          const dx = Math.abs(x - cx);
          const dz = Math.abs(z - cz);
          const isOuter = dx >= 12.0 || dz >= 12.0 || dx + dz >= 18.0;

          if (isOuter || y >= 7 || y === 0) {
            if (y === 4) {
              setBlock(x, y, z, wCutCopper);
            } else if (y === 8) {
              setBlock(x, y, z, groundPav);
            } else {
              setBlock(x, y, z, (x + z + y) % 5 === 0 ? calcite : stonePrim);
            }
          }
        }
      }
    }
  }

  // Interior Command Post / Bastion Core (Empty furnished interior)
  // Walls are at X=10, 21, Z=10, 21. Standable void at X: 11..20, Z: 11..20, Y: 1..6.
  fillBox(11, 1, 11, 20, 6, 20, "minecraft:air");

  // Interior Support Pilasters
  for (let y = 1; y <= 6; y++) {
    setBlock(11, y, 11, quartzPillar);
    setBlock(11, y, 20, quartzPillar);
    setBlock(20, y, 11, quartzPillar);
    setBlock(20, y, 20, quartzPillar);
  }

  // South Entry Tunnel into Bastion
  fillBox(15, 1, 21, 16, 3, 26, "minecraft:air");

  // South Grand Approach Stairs (Z = 26 to 31, X = 13 to 18)
  for (let step = 0; step <= 6; step++) {
    const sz = 31 - step;
    const sy = step + 1;
    for (let sx = 13; sx <= 18; sx++) {
      for (let y = 0; y < sy; y++) {
        setBlock(sx, y, sz, stonePrim);
      }
      setBlock(sx, sy, sz, `${quartzStairs}[facing=north,half=bottom]`);
    }
    // Stair Balustrades
    setBlock(12, sy + 1, sz, wCutCopper);
    setBlock(19, sy + 1, sz, wCutCopper);
  }

  // Bastion Promenade Parapets & Battlements (Y = 9)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isBastionRim(x, z)) {
        if ((x + z) % 2 === 0) {
          setBlock(x, 9, z, stoneWall);
        } else {
          setBlock(x, 9, z, wCopperSlab);
        }
      }
    }
  }

  // Defensive Shore Batteries / Energy Projectors (facing Sea Assault at North -Z)
  const turretCoords = [
    [5, 4],
    [26, 4],
    [5, 26],
    [26, 26]
  ];
  for (const [tx, tz] of turretCoords) {
    fillBox(tx - 1, 8, tz - 1, tx + 1, 9, tz + 1, wCutCopper);
    setBlock(tx, 10, tz, seaLantern);
    setBlock(tx, 11, tz, wCutCopper);
    if (tz < 16) {
      setBlock(tx, 10, tz - 1, "minecraft:lightning_rod[facing=north]");
      setBlock(tx, 9, tz - 1, prismarineWall);
    }
  }

  // Energy Conduits embedded in Promenade Floor
  for (let step = 9; step <= 22; step++) {
    setBlock(step, 8, 15, seaLantern);
    setBlock(15, 8, step, seaLantern);
  }

  // -------------------------------------------------------------
  // 2. MONUMENTAL STATUE PEDESTAL (Y = 8 to 14)
  // -------------------------------------------------------------
  // Stepped Plinth Base
  fillBox(8, 8, 8, 23, 8, 23, stonePrim);
  fillBox(9, 9, 9, 22, 9, 22, calcite);
  for (let x = 9; x <= 22; x++) {
    setBlock(x, 9, 9, `${quartzStairs}[facing=north,half=bottom]`);
    setBlock(x, 9, 22, `${quartzStairs}[facing=south,half=bottom]`);
  }
  for (let z = 9; z <= 22; z++) {
    setBlock(9, 9, z, `${quartzStairs}[facing=west,half=bottom]`);
    setBlock(22, 9, z, `${quartzStairs}[facing=east,half=bottom]`);
  }

  fillBox(10, 10, 10, 21, 10, 21, wCutCopper);

  // Pedestal Shaft (Y = 11 to 12)
  fillBox(11, 11, 11, 20, 12, 20, quartz);
  for (let y = 11; y <= 12; y++) {
    // Corner fluted pilasters
    setBlock(11, y, 11, quartzPillar);
    setBlock(11, y, 20, quartzPillar);
    setBlock(20, y, 11, quartzPillar);
    setBlock(20, y, 20, quartzPillar);

    // Inset decorative reliefs
    setBlock(15, y, 10, chiseledQuartz);
    setBlock(16, y, 10, chiseledQuartz);
    setBlock(15, y, 21, chiseledQuartz);
    setBlock(16, y, 21, chiseledQuartz);
    setBlock(10, y, 15, chiseledQuartz);
    setBlock(10, y, 16, chiseledQuartz);
    setBlock(21, y, 15, chiseledQuartz);
    setBlock(21, y, 16, chiseledQuartz);
  }

  // Pedestal Entablature & Capital (Y = 13)
  fillBox(10, 13, 10, 21, 13, 21, wCutCopper);
  for (let x = 10; x <= 21; x++) {
    setBlock(x, 13, 10, `${quartzStairs}[facing=north,half=top]`);
    setBlock(x, 13, 21, `${quartzStairs}[facing=south,half=top]`);
  }
  for (let z = 10; z <= 21; z++) {
    setBlock(10, 13, z, `${quartzStairs}[facing=west,half=top]`);
    setBlock(21, 13, z, `${quartzStairs}[facing=east,half=top]`);
  }

  // Statue Footing Plinth (Y = 14)
  fillBox(11, 14, 11, 20, 14, 20, quartz);

  // -------------------------------------------------------------
  // 3. ATHENA PROMACHOS COLOSSUS (Y = 14 to 54)
  // -------------------------------------------------------------

  // A. Flowing Peplos / Skirt Drapery (Y = 14 to 30)
  for (let y = 14; y <= 30; y++) {
    const t = (y - 14) / 16.0;
    const bodyCx = 15.5;
    const bodyCz = 15.5 + 0.2 * (1.0 - t);

    // Contrapposto flare and taper
    const rx = 4.8 * (1.0 - 0.44 * t);
    const rz = 4.3 * (1.0 - 0.44 * t);

    for (let x = Math.floor(bodyCx - rx - 1.5); x <= Math.ceil(bodyCx + rx + 1.5); x++) {
      for (let z = Math.floor(bodyCz - rz - 1.5); z <= Math.ceil(bodyCz + rz + 1.5); z++) {
        const dx = x - bodyCx;
        const dz = z - bodyCz;
        const angle = Math.atan2(dz, dx);

        // Fluted classical drapery fold wave
        const fold = (1.0 - 0.4 * t) * (0.35 * Math.sin(angle * 10) + 0.2 * Math.cos(angle * 6 + y * 0.4));
        const radNorm = (dx / (rx + fold)) ** 2 + (dz / (rz + fold)) ** 2;

        // Left leg bent forward prominence (Knee at Y: 18..25, X: 13.5, Z: 13.0)
        const leftKneeDist = Math.hypot(x - 13.5, z - 13.0);
        const isKnee = y >= 18 && y <= 25 && leftKneeDist <= 1.5;

        if (radNorm <= 1.05 || isKnee) {
          if (y === 14) {
            setBlock(x, y, z, (x + z) % 2 === 0 ? wCutCopper : wCopper);
          } else if (fold < -0.12) {
            setBlock(x, y, z, chiseledQuartz);
          } else if (fold > 0.18) {
            setBlock(x, y, z, quartz);
          } else {
            setBlock(x, y, z, (x + y + z) % 4 === 0 ? calcite : quartz);
          }
        }
      }
    }
  }

  // B. Belt / Girdle of Athena (Y = 30 to 31)
  for (let y = 30; y <= 31; y++) {
    for (let x = 13; x <= 18; x++) {
      for (let z = 13; z <= 18; z++) {
        const dx = (x - 15.5) / 2.7;
        const dz = (z - 15.5) / 2.3;
        if (dx * dx + dz * dz <= 1.05) {
          setBlock(x, y, z, wCutCopper);
        }
      }
    }
    // Golden Buckle / Meander Clasp at Front
    setBlock(15, y, 13, gold);
    setBlock(16, y, 13, gold);
  }

  // C. Torso, Cuirass & Aegis Gorgoneion (Y = 32 to 41)
  for (let y = 32; y <= 41; y++) {
    const t = (y - 32) / 9.0;
    const rx = 2.6 + 1.8 * t;
    const rz = 2.2 + 0.5 * t;

    for (let x = Math.floor(15.5 - rx - 0.5); x <= Math.ceil(15.5 + rx + 0.5); x++) {
      for (let z = Math.floor(15.5 - rz - 0.5); z <= Math.ceil(15.5 + rz + 0.5); z++) {
        const dx = (x - 15.5) / rx;
        const dz = (z - 15.5) / rz;
        if (dx * dx + dz * dz <= 1.0) {
          setBlock(x, y, z, (x + y) % 3 === 0 ? calcite : quartz);
        }
      }
    }
  }

  // Gorgoneion (Medusa Aegis Emblazoned on Chest at Y: 36..38, Z: 13, X: 14..17)
  setBlock(15, 37, 13, gold);
  setBlock(16, 37, 13, gold);
  setBlock(15, 38, 13, seaLantern);
  setBlock(16, 38, 13, seaLantern);
  setBlock(14, 37, 13, wCutCopper);
  setBlock(17, 37, 13, wCutCopper);
  setBlock(15, 36, 13, wCutCopper);
  setBlock(16, 36, 13, wCutCopper);

  // Billowing Neoclassical Cloak / Cape (Y = 31 to 41, Z = 17 to 20)
  for (let y = 31; y <= 41; y++) {
    const capeWidth = 3.5 + 1.2 * ((y - 31) / 10.0);
    const wave = 0.5 * Math.sin(y * 0.7);
    for (let x = Math.floor(15.5 - capeWidth); x <= Math.ceil(15.5 + capeWidth); x++) {
      const cz = Math.round(17.5 + wave + 0.3 * Math.sin(x * 1.5));
      setBlock(x, y, cz, quartz);
      if (Math.abs(x - 15.5) >= capeWidth - 0.6) {
        setBlock(x, y, cz, wCutCopper);
      }
    }
  }

  // D. Left Arm & Elevated Aegis Hoplon Shield (Facing North -Z toward Sea Assault)
  // Left Shoulder -> Forearm
  fillBox(11, 39, 15, 12, 41, 16, quartz);
  fillBox(9, 37, 13, 11, 39, 15, quartz);
  fillBox(8, 35, 11, 10, 37, 13, quartz);

  // Colossal Hoplon Shield Disk
  const shieldCx = 7.5;
  const shieldCy = 35.5;
  const shieldCz = 9.0;
  const shieldRad = 5.2;

  for (let sx = 2; sx <= 13; sx++) {
    for (let sy = 30; sy <= 41; sy++) {
      const dx = sx - shieldCx;
      const dy = sy - shieldCy;
      const r = Math.sqrt(dx * dx + dy * dy);

      if (r <= shieldRad) {
        // Shield convexity towards North (-Z)
        const curve = Math.sqrt(Math.max(0, shieldRad * shieldRad - r * r)) * 0.32;
        const sz = Math.round(shieldCz - curve + dx * 0.12);

        // Shield Layers: Rim, Field, Radiant Rays, Umbo
        if (r >= 4.0) {
          setBlock(sx, sy, sz, wCutCopper);
          setBlock(sx, sy, sz + 1, oxCutCopper);
        } else if (r <= 1.4) {
          // Central Protective Umbo (Force Projector)
          setBlock(sx, sy, sz, seaLantern);
          setBlock(sx, sy, sz - 1, gold);
        } else if (Math.abs(dx) <= 0.6 || Math.abs(dy) <= 0.6 || Math.abs(dx - dy) <= 0.6 || Math.abs(dx + dy) <= 0.6) {
          setBlock(sx, sy, sz, wCopper);
        } else {
          setBlock(sx, sy, sz, (sx + sy) % 2 === 0 ? quartz : calcite);
        }
      }
    }
  }

  // E. Right Arm & Colossal Energy Spear (Y = 34 to 52)
  // Right Shoulder -> Raised Hand
  fillBox(19, 39, 15, 20, 41, 16, quartz);
  fillBox(20, 41, 16, 22, 43, 18, quartz);
  fillBox(21, 42, 14, 22, 43, 16, quartz);

  // Spear Trajectory: Thrusting forward-down towards incoming marine assault
  // P0 (Butt Sauroter) = [24, 48, 23], P1 (Hand) = [21.5, 42.5, 15], P2 (Tip) = [16, 34, 1]
  const pStart = [24.0, 48.0, 23.0];
  const pEnd = [16.0, 34.0, 1.0];
  const steps = 80;

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const px = pStart[0] + (pEnd[0] - pStart[0]) * t;
    const py = pStart[1] + (pEnd[1] - pStart[1]) * t;
    const pz = pStart[2] + (pEnd[2] - pStart[2]) * t;

    const ix = Math.round(px);
    const iy = Math.round(py);
    const iz = Math.round(pz);

    if (pz > 6.0) {
      // Spear Shaft & Grip
      setBlock(ix, iy, iz, wCopper);
      if (pz >= 21.0) {
        // Sauroter Butt Spike
        setBlock(ix, iy, iz, gold);
      }
    } else {
      // Colossal Energy Spearhead (Z = 1 to 6)
      setBlock(ix, iy, iz, seaLantern);
      // Blade flanges
      setBlock(ix + 1, iy, iz, `${wCopperStairs}[facing=west,half=bottom]`);
      setBlock(ix - 1, iy, iz, `${wCopperStairs}[facing=east,half=bottom]`);
      setBlock(ix, iy + 1, iz, prismarineWall);
      setBlock(ix, iy - 1, iz, prismarineWall);
    }
  }
  // Radiant Spearpoint Tip
  setBlock(16, 34, 1, "minecraft:lightning_rod[facing=north]");
  setBlock(16, 34, 2, seaLantern);

  // F. Neck, Visage & Corinthian Helmet (Y = 42 to 54)
  // Neck
  fillBox(15, 42, 15, 16, 43, 16, quartz);

  // Face & Head Base (Y = 44 to 47)
  fillBox(14, 44, 14, 17, 47, 17, quartz);

  // Classical Features (Facing North -Z)
  setBlock(15, 44, 13, quartz); // Chin
  setBlock(16, 44, 13, quartz);
  setBlock(15, 45, 13, quartz); // Nose Bridge
  setBlock(16, 45, 13, quartz);
  setBlock(15, 46, 13, quartz);

  // Piercing Divine Eyes
  setBlock(14, 46, 13, seaLantern);
  setBlock(17, 46, 13, seaLantern);

  // Corinthian Helmet Cheekguards & Brow
  setBlock(13, 44, 13, wCutCopper);
  setBlock(13, 45, 13, wCutCopper);
  setBlock(18, 44, 13, wCutCopper);
  setBlock(18, 45, 13, wCutCopper);
  fillBox(14, 47, 13, 17, 47, 13, wCutCopper); // Nasal & Brow Guard

  // Helmet Cranium Dome (Y = 48 to 50)
  fillBox(13, 48, 13, 18, 50, 18, wCopper);
  fillBox(14, 49, 14, 17, 50, 17, oxCopper);

  // High Sweeping Hellenic Helmet Crest (Lophos) (Y = 48 to 54)
  for (let hz = 12; hz <= 20; hz++) {
    const u = (hz - 12) / 8.0;
    const crestApex = 49.0 + 5.0 * Math.sin(u * Math.PI);
    const topY = Math.round(crestApex);
    const bottomY = Math.round(crestApex - 2.5);

    for (let cy = bottomY; cy <= topY; cy++) {
      for (let cxPos = 15; cxPos <= 16; cxPos++) {
        if (cy === topY) {
          setBlock(cxPos, cy, hz, oxCutCopper);
        } else {
          setBlock(cxPos, cy, hz, oxCopper);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // EMIT DETERMINISTIC VOXEL STREAM
  // -------------------------------------------------------------
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const blk = grid.get(`${x},${y},${z}`);
        if (blk) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  return {
    name: "monumental_athena_colossus",
    seatY: 0,
    anchors: {
      front: [16, 0, 0],
      entrance: [16, 0, 31],
      bastion_deck: [16, 8, 22],
      spear_tip: [16, 34, 1],
      shield_boss: [7, 35, 7]
    },
    interiors: [
      {
        min: [11, 1, 11],
        max: [20, 6, 20],
        kind: "hall"
      }
    ]
  };
}

deepsea_beast.source:
export const envelope = [16, 14, 16];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  const rand = () => api.random();

  function setVoxel(x, y, z, block) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid[ix][iy][iz] = block;
    }
  }

  function getVoxel(x, y, z) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      return grid[ix][iy][iz];
    }
    return null;
  }

  function drawEllipsoid(cx, cy, cz, rx, ry, rz, blockFunc) {
    const minX = Math.max(0, Math.floor(cx - rx));
    const maxX = Math.min(W - 1, Math.ceil(cx + rx));
    const minY = Math.max(0, Math.floor(cy - ry));
    const maxY = Math.min(H - 1, Math.ceil(cy + ry));
    const minZ = Math.max(0, Math.floor(cz - rz));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rz));

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const dx = (x - cx) / rx;
          const dy = (y - cy) / ry;
          const dz = (z - cz) / rz;
          const distSq = dx * dx + dy * dy + dz * dz;
          if (distSq <= 1.0) {
            const blk = typeof blockFunc === "function" ? blockFunc(x, y, z, distSq, cx, cy, cz) : blockFunc;
            if (blk) grid[x][y][z] = blk;
          }
        }
      }
    }
  }

  function drawTaperedCapsule(p1, p2, r1, r2, blockFunc) {
    const dist = Math.hypot(p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2]);
    const steps = Math.max(1, Math.ceil(dist * 3.5));
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const cx = p1[0] + (p2[0] - p1[0]) * t;
      const cy = p1[1] + (p2[1] - p1[1]) * t;
      const cz = p1[2] + (p2[2] - p1[2]) * t;
      const r = r1 + (r2 - r1) * t;
      drawEllipsoid(cx, cy, cz, r, r, r, blockFunc);
    }
  }

  function drawLine(p1, p2, block) {
    const dist = Math.hypot(p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2]);
    const steps = Math.max(1, Math.ceil(dist * 2));
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      setVoxel(
        p1[0] + (p2[0] - p1[0]) * t,
        p1[1] + (p2[1] - p1[1]) * t,
        p1[2] + (p2[2] - p1[2]) * t,
        block
      );
    }
  }

  // Procedural beast variations
  const stanceType = Math.floor(rand() * 3); // 0: Lunging crawler, 1: Armored Behemoth, 2: Rearing Ravager
  const headYaw = (rand() - 0.5) * 2.2;
  const jawGap = 1.4 + rand() * 1.5;
  const archHeight = 6.2 + rand() * 2.0;
  const tailCurve = (rand() - 0.5) * 3.6;
  const tailHeight = 1.2 + rand() * 3.2;
  const hornStyle = Math.floor(rand() * 4);
  const finPattern = Math.floor(rand() * 3);
  const rightClawStrike = stanceType === 2 || rand() > 0.45;
  const stripePhase = Math.floor(rand() * 5);

  // Organic Shading logic for deepsea beast tissue & armor
  function bodyShader(x, y, z, distSq, cx, cy, cz) {
    const dy = y - cy;
    const dx = Math.abs(x - cx);

    // Dorsal armor plates (top)
    if (dy > 0.6) {
      if ((x + z + stripePhase) % 4 === 0) {
        return "minecraft:crying_obsidian";
      }
      return (x + z) % 2 === 0 ? "minecraft:dark_prismarine" : "minecraft:prismarine_bricks";
    }

    // Lateral bioluminescent line
    if (Math.abs(dy) <= 0.7 && dx >= 1.2) {
      if ((z + stripePhase) % 3 === 0) {
        return "minecraft:sea_lantern";
      }
      return "minecraft:dark_prismarine";
    }

    // Ventral underbelly scutes
    if (dy < -0.6) {
      if (z % 2 === 0) {
        return "minecraft:bone_block[axis=x]";
      }
      return "minecraft:prismarine";
    }

    // Core flanks
    return (x + y + z) % 3 === 0 ? "minecraft:prismarine_bricks" : "minecraft:dark_prismarine";
  }

  // 1. SKELETON SPINE KEYPOINTS
  const headZ = 3.2;
  const headY = stanceType === 2 ? 8.2 : stanceType === 1 ? 5.2 : 6.8;
  const headX = 7.5 + headYaw;

  const upperSnoutPos = [headX + headYaw * 0.2, headY + 0.4 + jawGap * 0.2, 1.0];
  const lowerSnoutPos = [headX + headYaw * 0.2, Math.max(1.8, headY - jawGap * 0.8), 1.2];
  const headPos = [headX, headY, headZ];
  const neckPos = [7.5 + headYaw * 0.4, (headY + archHeight) * 0.52, 4.8];
  const chestPos = [7.5, archHeight, 6.8];
  const midBodyPos = [7.5 - tailCurve * 0.2, archHeight - 0.4, 9.0];
  const hipPos = [7.5 - tailCurve * 0.5, archHeight - 1.4, 11.2];
  const tailMidPos = [7.5 - tailCurve * 1.0, Math.max(2.0, (archHeight - 1.4) * 0.55 + tailHeight * 0.5), 13.2];
  const tailTipPos = [7.5 - tailCurve * 1.8, Math.max(1.2, tailHeight), 15.0];

  // 2. MAIN BODY MASS CAPSULES
  drawTaperedCapsule(upperSnoutPos, headPos, 1.2, 2.0, bodyShader);
  drawTaperedCapsule(lowerSnoutPos, [headPos[0], headPos[1] - 0.8, headPos[2]], 1.0, 1.6, bodyShader);
  drawTaperedCapsule(headPos, neckPos, 2.0, 2.6, bodyShader);
  drawTaperedCapsule(neckPos, chestPos, 2.6, 3.2, bodyShader);
  drawTaperedCapsule(chestPos, midBodyPos, 3.2, 2.9, bodyShader);
  drawTaperedCapsule(midBodyPos, hipPos, 2.9, 2.3, bodyShader);
  drawTaperedCapsule(hipPos, tailMidPos, 2.3, 1.6, bodyShader);
  drawTaperedCapsule(tailMidPos, tailTipPos, 1.6, 0.9, bodyShader);

  // 3. TOOTH-RIMMED JAWS & GULLET
  // Upper jaw teeth
  const uX = upperSnoutPos[0];
  const uY = upperSnoutPos[1];
  for (let z = 1; z <= 3; z++) {
    setVoxel(uX - 1.0, uY - 0.9, z, "minecraft:end_rod[facing=down]");
    setVoxel(uX + 1.0, uY - 0.9, z, "minecraft:end_rod[facing=down]");
  }
  setVoxel(uX, uY - 0.8, 1, "minecraft:bone_block[axis=y]");

  // Lower jaw teeth
  const lX = lowerSnoutPos[0];
  const lY = lowerSnoutPos[1];
  for (let z = 1; z <= 3; z++) {
    setVoxel(lX - 0.9, lY + 0.9, z, "minecraft:end_rod[facing=up]");
    setVoxel(lX + 0.9, lY + 0.9, z, "minecraft:end_rod[facing=up]");
  }
  setVoxel(lX, lY + 0.8, 1, "minecraft:bone_block[axis=y]");

  // Gaping gullet / inner mouth glow
  setVoxel(headX, headY - 0.3, 2.4, "minecraft:sea_lantern");

  // Glowing Abyssal Eyes
  setVoxel(headX - 1.8, headY + 0.4, headZ - 0.5, "minecraft:sea_lantern");
  setVoxel(headX + 1.8, headY + 0.4, headZ - 0.5, "minecraft:sea_lantern");
  // Multi-eye secondary sockets
  setVoxel(headX - 1.5, headY + 1.1, headZ + 0.1, "minecraft:sea_lantern");
  setVoxel(headX + 1.5, headY + 1.1, headZ + 0.1, "minecraft:sea_lantern");

  // 4. CEPHALIC HORNS / CRESTS
  if (hornStyle === 0) {
    // Grand Curved Leviathan Horn
    const p0 = [headX, headY + 1.8, headZ - 0.5];
    const p1 = [headX, headY + 3.2, headZ + 0.8];
    const p2 = [headX, Math.min(13, headY + 4.2), headZ + 2.0];
    drawTaperedCapsule(p0, p1, 0.9, 0.6, "minecraft:bone_block[axis=z]");
    drawTaperedCapsule(p1, p2, 0.6, 0.3, "minecraft:bone_block[axis=z]");
    setVoxel(p2[0], p2[1], p2[2], "minecraft:sea_lantern");
  } else if (hornStyle === 1) {
    // Dual Flaring Crown Horns
    const lh0 = [headX - 1.2, headY + 1.5, headZ];
    const lh1 = [headX - 2.5, headY + 2.6, headZ + 0.8];
    const lh2 = [headX - 3.4, Math.min(13, headY + 3.4), headZ + 1.8];
    drawTaperedCapsule(lh0, lh1, 0.8, 0.5, "minecraft:bone_block[axis=x]");
    drawTaperedCapsule(lh1, lh2, 0.5, 0.3, "minecraft:bone_block[axis=z]");

    const rh0 = [headX + 1.2, headY + 1.5, headZ];
    const rh1 = [headX + 2.5, headY + 2.6, headZ + 0.8];
    const rh2 = [headX + 3.4, Math.min(13, headY + 3.4), headZ + 1.8];
    drawTaperedCapsule(rh0, rh1, 0.8, 0.5, "minecraft:bone_block[axis=x]");
    drawTaperedCapsule(rh1, rh2, 0.5, 0.3, "minecraft:bone_block[axis=z]");
  } else if (hornStyle === 2) {
    // Serrated Sawtooth Dorsal Blade
    for (let z = 1; z <= 4; z++) {
      const by = headY + 1.2 + (z === 2 || z === 3 ? 1.6 : 0.8);
      setVoxel(headX, by, z, "minecraft:dark_prismarine");
      setVoxel(headX, Math.min(13, by + 1), z, "minecraft:prismarine_wall");
    }
  } else {
    // Trident Cephalic Spikes
    setVoxel(headX, headY + 1.6, headZ - 1.0, "minecraft:bone_block[axis=z]");
    setVoxel(headX, headY + 1.6, headZ - 2.0, "minecraft:end_rod[facing=north]");
    setVoxel(headX - 1.4, headY + 1.8, headZ - 0.4, "minecraft:bone_block[axis=x]");
    setVoxel(headX - 2.2, headY + 2.4, headZ - 0.8, "minecraft:end_rod[facing=north]");
    setVoxel(headX + 1.4, headY + 1.8, headZ - 0.4, "minecraft:bone_block[axis=x]");
    setVoxel(headX + 2.2, headY + 2.4, headZ - 0.8, "minecraft:end_rod[facing=north]");
  }

  // 5. DORSAL SPINES & BIOLUMINESCENT RIDGES ALONG BACK
  for (let z = 4; z <= 14; z++) {
    // Find top surface voxel
    for (let x = 4; x <= 11; x++) {
      for (let y = H - 2; y >= 2; y--) {
        if (grid[x][y][z] !== null && grid[x][y + 1][z] === null) {
          if (Math.abs(x - 7.5) <= 1.0) {
            if (finPattern === 0) {
              setVoxel(x, y + 1, z, "minecraft:prismarine_wall");
              if ((z === 6 || z === 8 || z === 10) && y + 2 < H) {
                setVoxel(x, y + 2, z, "minecraft:prismarine_wall");
              }
            } else if (finPattern === 1) {
              if (z % 2 === 0) {
                setVoxel(x, y + 1, z, "minecraft:sea_lantern");
                if (y + 2 < H) setVoxel(x, y + 2, z, "minecraft:prismarine_wall");
              } else {
                setVoxel(x, y + 1, z, "minecraft:dark_prismarine");
              }
            } else {
              setVoxel(x, y + 1, z, "minecraft:bone_block[axis=y]");
              if (y + 2 < H) setVoxel(x, y + 2, z, "minecraft:end_rod[facing=up]");
            }
          }
          break;
        }
      }
    }
  }

  // 6. FORELIMBS & THRASHING CLAWED APPENDAGES
  function buildClawFoot(wristX, wristY, wristZ, facingNorth) {
    const dz = facingNorth ? -1.2 : 0.8;
    const digits = [
      [wristX - 1.1, wristY - 0.8, wristZ + dz],
      [wristX, wristY - 0.8, wristZ + dz * 1.3],
      [wristX + 1.1, wristY - 0.8, wristZ + dz]
    ];
    for (const [dx, dy, dzPoint] of digits) {
      drawTaperedCapsule([wristX, wristY, wristZ], [dx, dy, dzPoint], 0.6, 0.3, "minecraft:bone_block[axis=z]");
      setVoxel(dx, dy, dzPoint, "minecraft:crying_obsidian");
    }
  }

  // Front-Left Forelimb (Clawing onto shore)
  const flShoulder = [chestPos[0] - 2.5, chestPos[1] - 0.6, chestPos[2] - 0.6];
  const flElbow = [chestPos[0] - 4.2, Math.max(2.5, (chestPos[1] + 1.0) * 0.52), chestPos[2] - 1.2];
  const flGroundY = Math.max(0, Math.min(8, Math.round(api.heightAt(chestPos[0] - 3.8, chestPos[2] - 3.0))));
  const flWrist = [chestPos[0] - 3.8, flGroundY + 1.4, chestPos[2] - 3.0];

  drawTaperedCapsule(flShoulder, flElbow, 1.5, 1.2, "minecraft:dark_prismarine");
  drawTaperedCapsule(flElbow, flWrist, 1.2, 0.9, "minecraft:prismarine_bricks");
  buildClawFoot(flWrist[0], flWrist[1], flWrist[2], true);

  // Front-Right Forelimb (Lunging claw strike or grounded grip)
  const frShoulder = [chestPos[0] + 2.5, chestPos[1] - 0.6, chestPos[2] - 0.6];
  if (rightClawStrike) {
    // Raised mid-air swipe
    const frElbow = [chestPos[0] + 4.5, chestPos[1] + 1.2, chestPos[2] - 0.6];
    const frWrist = [chestPos[0] + 3.8, chestPos[1] + 1.8, chestPos[2] - 2.2];
    drawTaperedCapsule(frShoulder, frElbow, 1.5, 1.2, "minecraft:dark_prismarine");
    drawTaperedCapsule(frElbow, frWrist, 1.2, 0.9, "minecraft:prismarine_bricks");
    buildClawFoot(frWrist[0], frWrist[1], frWrist[2], true);
  } else {
    // Planted forward grip
    const frGroundY = Math.max(0, Math.min(8, Math.round(api.heightAt(chestPos[0] + 3.8, chestPos[2] - 3.0))));
    const frElbow = [chestPos[0] + 4.2, Math.max(2.5, (chestPos[1] + 1.0) * 0.52), chestPos[2] - 1.2];
    const frWrist = [chestPos[0] + 3.8, frGroundY + 1.4, chestPos[2] - 3.0];
    drawTaperedCapsule(frShoulder, frElbow, 1.5, 1.2, "minecraft:dark_prismarine");
    drawTaperedCapsule(frElbow, frWrist, 1.2, 0.9, "minecraft:prismarine_bricks");
    buildClawFoot(frWrist[0], frWrist[1], frWrist[2], true);
  }

  // Rear-Left Hindlimb
  const rlHip = [hipPos[0] - 2.2, hipPos[1] - 0.4, hipPos[2] - 0.2];
  const rlElbow = [hipPos[0] - 3.8, hipPos[1] + 0.6, hipPos[2] + 0.6];
  const rlGroundY = Math.max(0, Math.min(8, Math.round(api.heightAt(hipPos[0] - 3.2, hipPos[2] - 0.8))));
  const rlWrist = [hipPos[0] - 3.2, rlGroundY + 1.2, hipPos[2] - 0.8];

  drawTaperedCapsule(rlHip, rlElbow, 1.5, 1.2, "minecraft:dark_prismarine");
  drawTaperedCapsule(rlElbow, rlWrist, 1.2, 0.9, "minecraft:prismarine_bricks");
  buildClawFoot(rlWrist[0], rlWrist[1], rlWrist[2], false);

  // Rear-Right Hindlimb
  const rrHip = [hipPos[0] + 2.2, hipPos[1] - 0.4, hipPos[2] - 0.2];
  const rrElbow = [hipPos[0] + 3.8, hipPos[1] + 0.6, hipPos[2] + 0.6];
  const rrGroundY = Math.max(0, Math.min(8, Math.round(api.heightAt(hipPos[0] + 3.2, hipPos[2] - 0.8))));
  const rrWrist = [hipPos[0] + 3.2, rrGroundY + 1.2, hipPos[2] - 0.8];

  drawTaperedCapsule(rrHip, rrElbow, 1.5, 1.2, "minecraft:dark_prismarine");
  drawTaperedCapsule(rrElbow, rrWrist, 1.2, 0.9, "minecraft:prismarine_bricks");
  buildClawFoot(rrWrist[0], rrWrist[1], rrWrist[2], false);

  // 7. TAIL FIN / CAUDAL BLADE
  if (finPattern === 0) {
    // Horizontal marine fluke
    const tx = tailTipPos[0];
    const ty = tailTipPos[1];
    const tz = tailTipPos[2];
    setVoxel(tx - 1.5, ty, tz, "minecraft:dark_prismarine");
    setVoxel(tx - 2.2, ty + 0.5, tz, "minecraft:prismarine_wall");
    setVoxel(tx + 1.5, ty, tz, "minecraft:dark_prismarine");
    setVoxel(tx + 2.2, ty + 0.5, tz, "minecraft:prismarine_wall");
  } else if (finPattern === 1) {
    // Bioluminescent Scythe Fin
    const tx = tailTipPos[0];
    const ty = tailTipPos[1];
    const tz = tailTipPos[2];
    setVoxel(tx, ty + 1.2, tz, "minecraft:sea_lantern");
    setVoxel(tx, ty + 2.0, tz, "minecraft:bone_block[axis=y]");
    if (ty + 3.0 < H) setVoxel(tx, ty + 3.0, tz, "minecraft:end_rod[facing=up]");
  } else {
    // Barbed Chitinous Club
    drawEllipsoid(tailTipPos[0], tailTipPos[1], tailTipPos[2], 1.4, 1.4, 1.4, "minecraft:crying_obsidian");
    setVoxel(tailTipPos[0], tailTipPos[1] + 1.5, tailTipPos[2], "minecraft:prismarine_wall");
  }

  // 8. GROUND FOUNDATION PASS
  // Ensure every leg/foot column is solidly connected downward to terrain
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let lowestSolidY = -1;
      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] !== null) {
          lowestSolidY = y;
          break;
        }
      }
      if (lowestSolidY > 0 && lowestSolidY <= 4) {
        const groundLevel = Math.max(0, Math.min(H - 1, Math.round(api.heightAt(x, z))));
        if (lowestSolidY > groundLevel) {
          for (let fillY = groundLevel; fillY < lowestSolidY; fillY++) {
            grid[x][fillY][z] = "minecraft:dark_prismarine";
          }
        }
      }
    }
  }

  // 9. 6-CONNECTED COMPONENT FLOOD FILL & STRAY VOXEL CLEANUP
  const visited = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Uint8Array(D))
  );
  const solidList = [];
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] !== null) {
          solidList.push([x, y, z]);
        }
      }
    }
  }

  const dxs = [1, -1, 0, 0, 0, 0];
  const dys = [0, 0, 1, -1, 0, 0];
  const dzs = [0, 0, 0, 0, 1, -1];
  const components = [];

  for (const [sx, sy, sz] of solidList) {
    if (visited[sx][sy][sz]) continue;
    const comp = [];
    const queue = [[sx, sy, sz]];
    visited[sx][sy][sz] = 1;

    let head = 0;
    while (head < queue.length) {
      const [cx, cy, cz] = queue[head++];
      comp.push([cx, cy, cz]);
      for (let d = 0; d < 6; d++) {
        const nx = cx + dxs[d];
        const ny = cy + dys[d];
        const nz = cz + dzs[d];
        if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
          if (!visited[nx][ny][nz] && grid[nx][ny][nz] !== null) {
            visited[nx][ny][nz] = 1;
            queue.push([nx, ny, nz]);
          }
        }
      }
    }
    components.push(comp);
  }

  // Sort descending by voxel count
  components.sort((a, b) => b.length - a.length);

  // Keep largest body and bridge or drop strays
  if (components.length > 1) {
    const mainComp = components[0];
    for (let c = 1; c < components.length; c++) {
      const stray = components[c];
      let bestDist = 999999;
      let pA = null;
      let pB = null;
      for (const p of stray) {
        for (const m of mainComp) {
          const d = Math.abs(p[0] - m[0]) + Math.abs(p[1] - m[1]) + Math.abs(p[2] - m[2]);
          if (d < bestDist) {
            bestDist = d;
            pA = p;
            pB = m;
          }
        }
      }
      if (bestDist <= 3 && pA && pB) {
        drawLine(pA, pB, "minecraft:dark_prismarine");
      } else {
        for (const [x, y, z] of stray) {
          grid[x][y][z] = null;
        }
      }
    }
  }

  // 10. EMIT VOXELS TO API
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] !== null) {
          api.set(x, y, z, grid[x][y][z]);
        }
      }
    }
  }

  const frontAnchorX = Math.max(0, Math.min(W - 1, Math.round(headX)));
  const frontAnchorY = Math.max(0, Math.min(H - 1, Math.round(headY)));

  return {
    name: "Deepsea Beast",
    seatY: 0,
    anchors: {
      front: [frontAnchorX, frontAnchorY, 0]
    }
  };
}
